const crypto = global.get('crypto');
const values = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const now = new Date().toISOString().slice(0, 19);
const seq = Date.now();
const items = [
  { deviceCode: 'NR-TH01', pointCode: 'temperature', value: values[0] / 10, sampleTime: now, seq: seq },
  { deviceCode: 'NR-TH01', pointCode: 'humidity', value: values[1] / 10, sampleTime: now, seq: seq + 1 }
];
const body = JSON.stringify({ items });
const secret = '<SECRET>';
const sig = crypto.createHash('sha256').update(secret + body, 'utf8').digest('hex');
msg.method = 'POST';
msg.url = 'http://localhost:8081/api/ingest/samples';
msg.headers = { 'Content-Type': 'application/json', 'Authorization': 'Gateway <ACCESS_KEY>:' + sig };
msg.payload = body;
return msg;
